begin;

create or replace function private.official_slot_mechanics(
  p_class_key text,
  p_level integer,
  p_slots jsonb
)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',p_class_key || '-slot-' || e.key || '-l' || p_level::text,
    'type','resource','sourceKey','spellcasting','grantOperation','REPLACE','priority',p_level,
    'key','spell_slot_' || e.key,'label','Ячейки ' || e.key || ' уровня',
    'max',(e.value #>> '{}')::integer,'recharge',jsonb_build_array('long_rest'),
    'restore','full','initial','full',
    'presentation',jsonb_build_object('tone','violet','icon','✦','display','pips','priority',80)
  ) order by (e.key)::integer),'[]'::jsonb)
  from jsonb_each(coalesce(p_slots,'{}'::jsonb)) e;
$$;

