n":false,"usesScale":null},"runtime":[]},{"level":6,"key":"subclass","name":"Способность специализации","description":"Открывает очередную способность выбранного подкласса.","mechanic":{"economy":null,"dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"spellKeys":[],"recharge":[],"oncePerTurn":false,"usesScale":null},"runtime":[]},{"level":8,"key":"ability-score-improvement","name":"Улучшение характеристик","description":"Даёт улучшение характеристик или подходящий талант.","mechanic":{"economy":null,"dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"spellKeys":[],"recharge":[],"oncePerTurn":false,"usesScale":null},"runtime":[]},{"level":10,"key":"subclass","name":"Способность специализации","description":"Открывает очередную способность выбранного подкласса.","mechanic":{"economy":null,"dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"spellKeys":[],"recharge":[],"oncePerTurn":false,"usesScale":null},"runtime":[]},{"level":12,"key":"ability-score-improvement","name":"Улучшение характеристик","description":"Даёт улучшение характеристик или подходящий талант.","mechanic":{"economy":null,"dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"spellKeys":[],"recharge":[],"oncePerTurn":false,"usesScale":null},"runtime":[]},{"level":14,"key":"subclass","name":"Способность специализации","description":"Открывает очередную способность выбранного подкласса.","mechanic":{"economy":null,"dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"spellKeys":[],"recharge":[],"oncePerTurn":false,"usesScale":null},"runtime":[]},{"level":16,"key":"ability-score-improvement","name":"Улучшение характеристик","description":"Даёт улучшение характеристик или подходящий талант.","mechanic":{"economy":null,"dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"spellKeys":[],"recharge":[],"oncePerTurn":false,"usesScale":null},"runtime":[]},{"level":18,"key":"spell-mastery","name":"Мастерство заклинаний","description":"Мастерство заклинаний расширяет возможности волшебник на этом уровне. Восстановление: долгий отдых.","mechanic":{"economy":null,"dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"spellKeys":[],"recharge":["long_rest"],"oncePerTurn":false,"usesScale":null},"runtime":[]},{"level":19,"key":"epic-boon","name":"Эпический дар","description":"Открывает выбор эпического дара.","mechanic":{"economy":null,"dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"spellKeys":[],"recharge":[],"oncePerTurn":false,"usesScale":null},"runtime":[]},{"level":20,"key":"signature-spells","name":"Фирменные заклинания","description":"Фирменные заклинания расширяет возможности волшебник на этом уровне. Восстановление: короткий отдых или долгий отдых.","mechanic":{"economy":null,"dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"spellKeys":[],"recharge":["short_rest","long_rest"],"oncePerTurn":false,"usesScale":null},"runtime":[]}],"progression":{},"slots":[{"1":2},{"1":3},{"1":4,"2":2},{"1":4,"2":3},{"1":4,"2":3,"3":2},{"1":4,"2":3,"3":3},{"1":4,"2":3,"3":3,"4":1},{"1":4,"2":3,"3":3,"4":2},{"1":4,"2":3,"3":3,"4":3,"5":1},{"1":4,"2":3,"3":3,"4":3,"5":2},{"1":4,"2":3,"3":3,"4":3,"5":2,"6":1},{"1":4,"2":3,"3":3,"4":3,"5":2,"6":1},{"1":4,"2":3,"3":3,"4":3,"5":2,"6":1,"7":1},{"1":4,"2":3,"3":3,"4":3,"5":2,"6":1,"7":1},{"1":4,"2":3,"3":3,"4":3,"5":2,"6":1,"7":1,"8":1},{"1":4,"2":3,"3":3,"4":3,"5":2,"6":1,"7":1,"8":1},{"1":4,"2":3,"3":3,"4":3,"5":2,"6":1,"7":1,"8":1,"9":1},{"1":4,"2":3,"3":3,"4":3,"5":3,"6":1,"7":1,"8":1,"9":1},{"1":4,"2":3,"3":3,"4":3,"5":3,"6":2,"7":1,"8":1,"9":1},{"1":4,"2":3,"3":3,"4":3,"5":3,"6":2,"7":2,"8":1,"9":1}]}]$catalog$::jsonb;
  v_class jsonb;
  v_feature jsonb;
  v_mechanic jsonb;
  v_template uuid;
  v_level integer;
  v_base jsonb;
  v_level_mechanics jsonb;
  v_choices jsonb;
  v_slots jsonb;
begin
  for v_class in select value from jsonb_array_elements(v_catalog) loop
    v_base := jsonb_build_array(jsonb_build_object(
      'id',(v_class->>'key') || '-hit-die','type','grant','sourceKey','hit-die',
      'target','feature','key','class:' || (v_class->>'key') || ':hit-die',
      'payload',jsonb_build_object('label','Кость здоровья: к' || (v_class->>'hitDie'),'hitDie',(v_class->>'hitDie')::integer)
    ));

    for v_mechanic in select value from jsonb_array_elements(v_class->'saves') loop
      v_base := v_base || jsonb_build_array(jsonb_build_object(
        'id',(v_class->>'key') || '-save-' || (v_mechanic #>> '{}'),'type','grant',
        'sourceKey','saving-throw-' || (v_mechanic #>> '{}'),'target','proficiency',
        'key','savingThrow:' || (v_mechanic #>> '{}'),
        'payload',jsonb_build_object('rank',1,'label','Спасбросок: ' || case (v_mechanic #>> '{}')
          when 'strength' then 'Сила' when 'dexterity' then 'Ловкость' when 'constitution' then 'Телосложение'
          when 'intelligence' then 'Интеллект' when 'wisdom' then 'Мудрость' else 'Харизма' end)
      ));
    end loop;
    for v_mechanic in select value from jsonb_array_elements(v_class->'armors') loop
      v_base := v_base || jsonb_build_array(jsonb_build_object(
        'id',(v_class->>'key') || '-armor-' || (v_mechanic #>> '{}'),'type','grant',
        'sourceKey','armor-' || (v_mechanic #>> '{}'),'target','proficiency',
        'key','armor:' || (v_mechanic #>> '{}'),'payload',jsonb_build_object('rank',1,'label',
          case (v_mechanic #>> '{}') when 'light' then 'Лёгкие доспехи' when 'medium' then 'Средние доспехи'
          when 'heavy' then 'Тяжёлые доспехи' else 'Щиты' end)
      ));
    end loop;
    for v_mechanic in select value from jsonb_array_elements(v_class->'weapons') loop
      v_base := v_base || jsonb_build_array(jsonb_build_object(
        'id',(v_class->>'key') || '-weapon-' || (v_mechanic #>> '{}'),'type','grant',
        'sourceKey','weapon-' || (v_mechanic #>> '{}'),'target','proficiency',
        'key','weapon:' || (v_mechanic #>> '{}'),'payload',jsonb_build_object('rank',1,'label',
          case (v_mechanic #>> '{}') when 'simple' then 'Простое оружие' else 'Воинское оружие' end)
      ));
    end loop;
    for v_mechanic in select value from jsonb_array_elements(v_class->'tools') loop
      v_base := v_base || jsonb_build_array(jsonb_build_object(
        'id',(v_class->>'key') || '-tool-' || (v_mechanic #>> '{}'),'type','grant',
        'sourceKey','tool-' || (v_mechanic #>> '{}'),'target','proficiency',
        'key','tool:' || (v_mechanic #>> '{}'),'payload',jsonb_build_object('rank',1,'label',
          case (v_mechanic #>> '{}') when 'thieves-tools' then 'Воровские инструменты'
          when 'tinkers-tools' then 'Инструменты ремонтника' when 'artisans-tools-choice' then 'Ремесленные инструменты на выбор'
          else 'Музыкальный инструмент на выбор' end)
      ));
    end loop;

    insert into public.rule_templates(
      campaign_id,kind,slug,name,description,version,mechanics,choices,parent_template_id,unlock_level,
      catalog_key,catalog_revision,source_kind,source_label,is_builtin,mechanical_summary,
      author_description,author_comment,rules_meta,created_by,is_active
    ) values (
      p_campaign_id,'class',(v_class->>'key') || '-core',v_class->>'name',v_class->>'description',1,
      v_base,coalesce(v_class->'choices','[]'::jsonb),null,null,
      'class:' || (v_class->>'key'),'official-current@1','official','Official rules',true,
      v_class->>'summary',v_class->>'author',v_class->>'comment',
      jsonb_build_object(
        'class_key',v_class->>'key','hit_die',(v_class->>'hitDie')::integer,
        'spellcasting_ability',v_class->'ability','spell_progression',v_class->'spell',
        'sheet_profile',jsonb_strip_nulls(jsonb_build_object(
          'spellcasting_enabled',(v_class->>'spell') in ('full','half','pact'),
          'spellcasting_ability',v_class->'ability',
          'spell_list',v_class->>'key',
          'spell_slots_by_level',v_class->'slots'
        ))
      ),null,true
    )
    on conflict(campaign_id,kind,slug,version) do update set
      name=excluded.name,description=excluded.description,mechanics=excluded.mechanics,choices=excluded.choices,
      catalog_key=excluded.catalog_key,catalog_revision=excluded.catalog_revision,source_kind=excluded.source_kind,
      source_label=excluded.source_label,is_builtin=true,mechanical_summary=excluded.mechanical_summary,
      author_description=excluded.author_description,author_comment=excluded.author_comment,
      rules_meta=excluded.rules_meta,is_active=true,updated_at=now()
    returning id into v_template;

    delete from public.rule_template_levels where template_id=v_template;
    for v_level in 1..20 loop
      v_level_mechanics := '[]'::jsonb;
      v_slots := coalesce(v_class->'slots'->(v_level-1), '{}'::jsonb);
      if jsonb_typeof(v_slots)='object' and v_slots <> '{}'::jsonb then
        v_level_mechanics := v_level_mechanics || private.official_slot_mechanics(v_class->>'key',v_level,v_slots);
      end if;
      for v_feature in select value from jsonb_array_elements(v_class->'features')
        where (value->>'level')::integer=v_level
      loop
        v_level_mechanics := v_level_mechanics || jsonb_build_array(jsonb_build_object(
          'id',(v_class->>'key') || '-' || (v_feature->>'key') || '-feature-l' || v_level::text,
          'type','grant','sourceKey',v_feature->>'key','target','feature',
          'key','class:' || (v_class->>'key') || ':' || (v_feature->>'key'),
          'payload',jsonb_build_object(
            'label',v_feature->>'name','description',v_feature->>'description',
            'mechanic',coalesce(v_feature->'mechanic','{}'::jsonb)
          )
        ));
        v_level_mechanics := v_level_mechanics || coalesce(v_feature->'runtime','[]'::jsonb);
      end loop;
      v_level_mechanics := v_level_mechanics || coalesce(v_class->'progression'->v_level::text,'[]'::jsonb);
      insert into public.rule_template_levels(template_id,level,mechanics,choices)
      values(v_template,v_level,v_level_mechanics,'[]'::jsonb);
    end loop;
  end loop;

  -- Public-facing Druid copy is canon, not a changelog.
  update public.rule_templates set
    description=case catalog_key
      when 'class:druid' then 'Полный заклинатель природы с Дикой формой, поддержкой и управлением полем боя.'
      when 'subclass:druid:land' then 'Круг, который меняет природную настройку и набор возможностей после отдыха.'
      when 'subclass:druid:moon' then 'Круг боевых превращений, лунной магии и усиленной звериной формы.'
      when 'subclass:druid:sea' then 'Круг шторма, холода, отталкивания и морской мобильности.'
      when 'subclass:druid:stars' then 'Круг звёздных форм, знамений и направляющей магии.'
      else description end,
    mechanical_summary=case
      when catalog_key='class:druid' then 'К8 здоровья, Мудрость, полный заклинатель. Дикая форма требует действия, имеет два использования, принимает запас здоровья зверя и возвращается после короткого или долгого отдыха.'
      when catalog_key='subclass:druid:moon' then 'Усиленная звериная форма, круговые заклинания в облике зверя, Лунный шаг и Лунная форма.'
      else mechanical_summary end,
    updated_at=now()
  where catalog_key in ('class:druid','subclass:druid:land','subclass:druid:moon','subclass:druid:sea','subclass:druid:stars');

  update public.rule_templates t set mechanics=coalesce((
    select jsonb_agg(case m->>'id'
      when 'druid-spellcasting' then jsonb_set(m,'{payload,description}',to_jsonb('Полный подготовленный заклинатель на Мудрости. Ячейки и доступные уровни магии растут вместе с уровнем друида.'::text),true)
      else m end)
    from jsonb_array_elements(t.mechanics) m
  ),'[]'::jsonb)
  where t.catalog_key='class:druid';

  update public.rule_template_levels l set mechanics=coalesce((
    select jsonb_agg(case m->>'id'
      when 'druid-wild-shape-rules' then jsonb_set(jsonb_set(m,'{payload,label}',to_jsonb('Дикая форма'::text),true),'{payload,description}',to_jsonb('Действием превращается в виденного ранее зверя. Доступно два использования; оба возвращаются после короткого или долгого отдыха. Форма использует запас здоровья и физические параметры зверя.'::text),true)
      when 'druid-subclass-unlock' then jsonb_set(m,'{payload,description}',to_jsonb('На 3 уровне открывается выбор круга друида. Способности круга приходят вместе с уровнями класса.'::text),true)
      when 'druid-archdruid' then jsonb_set(m,'{payload,description}',to_jsonb('При инициативе помогает вернуть расход Дикой формы, позволяет преобразовать её запас в магию и сильно замедляет старение.'::text),true)
      when 'moon-circle-forms' then jsonb_set(m,'{payload,description}',to_jsonb('Максимальный CR зверя равен уровню друида, делённому на три. В форме можно использовать КД 13 + модификатор Мудрости, если КД зверя ниже.'::text),true)
      else m end)
    from jsonb_array_elements(l.mechanics) m
  ),'[]'::jsonb)
  from public.rule_templates t
  where l.template_id=t.id and t.catalog_key in ('class:druid','subclass:druid:moon');
end;
$$;

create or replace function private.install_official_class_catalog_after_campaign()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.install_official_class_catalog(new.id);
  return new;
end;
$$;

drop trigger if exists campaigns_install_official_class_catalog on public.campaigns;
create trigger campaigns_install_official_class_catalog
after insert on public.campaigns
for each row execute function private.install_official_class_catalog_after_campaign();

do $$
declare v_campaign record;
begin
  for v_campaign in select id from public.campaigns loop
    perform private.install_official_class_catalog(v_campaign.id);
  end loop;
end;
$$;

commit;
